        Dispatcher.UIThread.RunJobs();

        var allText = combo.GetVisualDescendants().OfType<TextBlock>().ToList();
        var descBlocks = allText
            .Where(tb => tb.Text is not null
                && (tb.Text.Contains("Plan all tasks", StringComparison.Ordinal)
                    || tb.Text!.Contains("One task at a time", StringComparison.Ordinal)
                    || tb.Text!.Contains("rebuilds and relaunches", StringComparison.Ordinal)))
            .ToList();

        Assert.Equal(3, descBlocks.Count);

        foreach (var tb in descBlocks)
        {
            var fgBrush = tb.Foreground as SolidColorBrush;
            Assert.NotNull(fgBrush);
            var fgHex = $"#{fgBrush!.Color.R:X2}{fgBrush.Color.G:X2}{fgBrush.Color.B:X2}";
            var bgHex = ResolveAncestorBackground(tb);

            var ratio = ContrastTests.ContrastRatio(fgHex, bgHex);
            Assert.True(ratio >= ContrastTests.AaNormal,
                $"Description {fgHex} on {bgHex}: {ratio:F2}:1 < {ContrastTests.AaNormal}:1");
        }

        var nameBlocks = allText
            .Where(tb => tb.Text is "Standard" or "Sequential" or "Restart Between Tasks")
            .ToList();
        Assert.Equal(3, nameBlocks.Count);

        foreach (var tb in nameBlocks)
        {
            var fgBrush = tb.Foreground as SolidColorBrush;
            Assert.NotNull(fgBrush);
            var fgHex = $"#{fgBrush!.Color.R:X2}{fgBrush.Color.G:X2}{fgBrush.Color.B:X2}";
            var bgHex = ResolveAncestorBackground(tb);

            var ratio = ContrastTests.ContrastRatio(fgHex, bgHex);
            Assert.True(ratio >= ContrastTests.AaNormal,
                $"Name {fgHex} on {bgHex}: {ratio:F2}:1 < {ContrastTests.AaNormal}:1");
        }
    }

    /// <summary>
    /// Walk the visual ancestor chain for the nearest Border with a
    /// non-transparent Background and return it as a #RRGGBB hex string.
    /// Falls back to the top-bar background #101218.
    /// </summary>
    private static string ResolveAncestorBackground(Avalonia.Visual leaf)
    {
        for (var el = leaf.VisualParent; el is not null; el = el.VisualParent)
        {
            if (el is Border border
                && border.Background is SolidColorBrush bg
                && bg.Color.A == 255)
            {
                return $"#{bg.Color.R:X2}{bg.Color.G:X2}{bg.Color.B:X2}";
            }

            if (el is Panel panel
                && panel.Background is SolidColorBrush pbg
                && pbg.Color.A == 255)
            {
                return $"#{pbg.Color.R:X2}{pbg.Color.G:X2}{pbg.Color.B:X2}";
            }
        }

        return "#101218";
    }
}

